:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --digit-bg: #0f3460;
  --digit-color: #e94560;
  --success: #2ecc71;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.lock-card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
  max-width: 480px;
  width: 100%;
}

h1 {
  font-size: 1.75rem;
  letter-spacing: 2px;
  color: var(--accent);
  text-transform: uppercase;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--muted);
  font-size: 0.95rem;
  margin-bottom: 28px;
}

.dials {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}

.dial {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.dial-btn {
  width: 56px;
  height: 44px;
  border: none;
  border-radius: 10px;
  background: var(--digit-bg);
  color: var(--text);
  font-size: 1.1rem;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dial-btn:hover {
  background: #1a4a7a;
}

.dial-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.dial-btn:active {
  transform: scale(0.92);
  background: var(--accent);
}

.digit {
  width: 56px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--digit-bg);
  border-radius: 10px;
  font-size: 2rem;
  font-weight: 700;
  color: var(--digit-color);
  font-variant-numeric: tabular-nums;
  box-shadow: inset 0 0 12px rgba(233, 69, 96, 0.2);
}

.open-btn {
  width: 100%;
  max-width: 220px;
  padding: 14px;
  border: none;
  border-radius: 10px;
  background: var(--accent);
  color: #fff;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 1px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.open-btn:hover {
  background: var(--accent-hover);
}

.open-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.open-btn:active {
  transform: scale(0.96);
}

.open-btn:disabled {
  background: var(--muted);
  cursor: not-allowed;
  transform: none;
}

.status {
  min-height: 1.5em;
  margin-top: 20px;
  font-weight: 600;
  font-size: 1rem;
}

.status.success {
  color: var(--success);
}

.status.error {
  color: var(--accent);
}

.attempts {
  margin-top: 8px;
  color: var(--muted);
  font-size: 0.9rem;
}

@media (max-width: 360px) {
  .lock-card {
    padding: 24px 16px;
  }

  .dials {
    gap: 10px;
  }

  .dial-btn {
    width: 48px;
    height: 40px;
  }

  .digit {
    width: 48px;
    height: 56px;
    font-size: 1.6rem;
  }

  h1 {
    font-size: 1.4rem;
  }
}

const COMBINATION = [3, 7, 2];
const digits = [0, 0, 0];
let failedAttempts = 0;
let unlocked = false;

const digitEls = [
  document.getElementById('digit-0'),
  document.getElementById('digit-1'),
  document.getElementById('digit-2'),
];
const statusEl = document.getElementById('status');
const attemptEl = document.getElementById('attempt-count');
const openBtn = document.getElementById('open-btn');

function render() {
  digitEls.forEach((el, i) => {
    el.textContent = digits[i];
  });
}

function adjustDial(index, direction) {
  if (unlocked) return;
  digits[index] = (digits[index] + direction + 10) % 10;
  render();
}

function tryOpen() {
  if (unlocked) return;

  const isCorrect = digits.every((d, i) => d === COMBINATION[i]);

  if (isCorrect) {
    unlocked = true;
    statusEl.textContent = 'Unlocked!'; 
    statusEl.className = 'status success';
    openBtn.disabled = true;
    document.querySelectorAll('.dial-btn').forEach(btn => btn.disabled = true);
  } else {
    failedAttempts++;
    attemptEl.textContent = failedAttempts;
    statusEl.textContent = 'Wrong combination. Try again.';
    statusEl.className = 'status error';
  }
}

// Dial buttons
const dialButtons = document.querySelectorAll('.dial-btn');
dialButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    const index = Number(btn.dataset.dial);
    const dir = Number(btn.dataset.dir);
    adjustDial(index, dir);
    // Clear status on new input
    if (!unlocked) {
      statusEl.textContent = '';
      statusEl.className = 'status';
    }
  });
});

// Open button
openBtn.addEventListener('click', tryOpen);

// Keyboard support for arrow keys on focused dial buttons (optional enhancement)
document.addEventListener('keydown', (e) => {
  if (unlocked) return;
  const target = document.activeElement;
  if (!target || !target.classList.contains('dial-btn')) return;

  const index = Number(target.dataset.dial);
  if (e.key === 'ArrowUp') {
    e.preventDefault();
    adjustDial(index, 1);
  } else if (e.key === 'ArrowDown') {
    e.preventDefault();
    adjustDial(index, -1);
  }
});

render();
